package main

import (
	"bytes"
	_ "embed"
	"image"
	"image/color"
	"image/png"

	ink "github.com/dennwc/inkview"
)

// The passbolt wordmark, generated by `make logos`: small for the headers,
// large for the loading screen.
var logoSmall, logoLarge = mustLogo(logoSmallPNG), mustLogo(logoLargePNG)

//go:embed images/logo-64.png
var logoSmallPNG []byte

//go:embed images/logo-148.png
var logoLargePNG []byte

// logo is a grayscale image stored as horizontal runs of one gray, so drawing
// it takes a few thousand FillArea calls instead of one DrawPixel per pixel.
// White is left out: the app draws on a white screen.
type logo struct {
	size image.Point
	runs []span
}

// span is a run of w pixels of one gray, starting at (x, y).
type span struct {
	x, y, w int
	gray    uint8
}

// mustLogo decodes an embedded PNG. It panics if the image is broken, which
// only a bad `make logos` can cause.
func mustLogo(data []byte) *logo {
	img, err := png.Decode(bytes.NewReader(data))
	if err != nil {
		panic("decoding logo: " + err.Error())
	}
	b := img.Bounds()
	l := &logo{size: b.Size()}
	for y := 0; y < l.size.Y; y++ {
		x0, g0 := 0, uint8(0xff)
		for x := 0; x <= l.size.X; x++ {
			g := uint8(0xff) // past the right edge: ends the last run
			if x < l.size.X {
				g = color.GrayModel.Convert(img.At(b.Min.X+x, b.Min.Y+y)).(color.Gray).Y
				g = g&0xf0 | g>>4 // the panel's 16 levels
			}
			if g == g0 {
				continue
			}
			if g0 != 0xff {
				l.runs = append(l.runs, span{x0, y, x - x0, g0})
			}
			x0, g0 = x, g
		}
	}
	return l
}

// draw draws l with its top-left corner at p.
func (l *logo) draw(p image.Point) {
	for _, r := range l.runs {
		x, y := p.X+r.x, p.Y+r.y
		ink.FillArea(image.Rect(x, y, x+r.w, y+1), color.Gray{Y: r.gray})
	}
}
